  const ONEWAY = { arr: ['36L', '18L'], dep: ['18R', '36R'] };
  const NIGHT_RWY = { at: [22*60 + 30, 6*60 + 30], arr: ['18C', '24', '36R', '04', '22', '09', '27'], dep: ['36C', '18L', '04', '22', '09', '27'] };
